package com.giftmarket.admin.service;import com.giftmarket.admin.exception.AdminExchangeException;import com.giftmarket.auth.exception.AuthenticationException;import com.giftmarket.order.entity.*;import com.giftmarket.order.repository.*;import com.giftmarket.payment.repository.ExchangeShippingPaymentRepository;import com.giftmarket.user.entity.*;import com.giftmarket.user.repository.UserRepository;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.data.domain.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.BDDMockito.given;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class AdminExchangeServiceTest{@Mock UserRepository users;@Mock ExchangeRequestRepository exchanges;@Mock ExchangeRequestItemRepository items;@Mock ExchangeShippingPaymentRepository payments;@Mock User admin;AdminExchangeService service;@BeforeEach void setUp(){service=new AdminExchangeService(users,exchanges,items,payments);}void admin(){given(users.findById(1L)).willReturn(Optional.of(admin));given(admin.getRole()).willReturn(UserRole.ADMIN);}@Test void rejectsNullAdmin(){assertThatThrownBy(()->service.getExchanges(null,0,20,null,null,null)).isInstanceOf(AuthenticationException.class);verifyNoInteractions(exchanges);}@Test void rejectsMissingAdmin(){given(users.findById(1L)).willReturn(Optional.empty());assertThatThrownBy(()->service.getExchange(1L,2L)).isInstanceOf(AuthenticationException.class).hasMessage("사용자를 찾을 수 없습니다.");}@Test void rejectsNonAdmin(){given(users.findById(1L)).willReturn(Optional.of(admin));given(admin.getRole()).willReturn(UserRole.USER);assertThatThrownBy(()->service.getExchange(1L,2L)).isInstanceOf(AuthenticationException.class).hasMessage("관리자 권한이 필요합니다.");}@Test void passesTrimmedFiltersPaginationAndSort(){admin();given(exchanges.findAdminExchanges(any(),any(),any(),any())).willReturn(Page.empty());service.getExchanges(1L,2,20," gift ",ExchangeRequestStatus.PAYMENT_PENDING,ExchangeResponsibility.BUYER);ArgumentCaptor<Pageable>p=ArgumentCaptor.forClass(Pageable.class);verify(exchanges).findAdminExchanges(eq("gift"),eq(ExchangeRequestStatus.PAYMENT_PENDING),eq(ExchangeResponsibility.BUYER),p.capture());assertThat(p.getValue().getPageNumber()).isEqualTo(2);assertThat(p.getValue().getSort().getOrderFor("requestedAt").isDescending()).isTrue();assertThat(p.getValue().getSort().getOrderFor("id").isDescending()).isTrue();}@Test void emptyPageSkipsBatches(){admin();given(exchanges.findAdminExchanges(any(),any(),any(),any())).willReturn(Page.empty());assertThat(service.getExchanges(1L,0,20," ",null,null).content()).isEmpty();verifyNoInteractions(items,payments);}@Test void throwsNotFound(){admin();given(exchanges.findAdminById(99L)).willReturn(Optional.empty());assertThatThrownBy(()->service.getExchange(1L,99L)).isInstanceOf(AdminExchangeException.class).hasMessage("교환 요청을 찾을 수 없습니다.");}}
